{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [event("a", 1, True), event("b", 1, None), event("c", 1, False)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([event("d", 1, None)]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_empty_groups(groups):
    assert pooled_flag_rate(groups) == 0.0
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert top_flagged_groups(groups, 3) == []


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (10, 10)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parser_flag_values_whitespace_and_skipped_lines():
    lines = ["", "  \t\n", "# comment", "  # another,comment", " a , 2 , 1 \n", "b, -1, 0", " c,3, \n"]
    assert parse_transcript_log(iter(lines)) == [
        event("a", 2, True), event("b", -1, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1.5,0", "a,,1"])
def test_parser_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "valid,1,0", "  ", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts():
    events = [
        event("z", 0, True),
        event("b", 2, True),
        event("a", 2, False),
        event("z", 3, None),
        event("b", 1, False),
        event("c", 2, True),
    ]
    assert dedupe_transcripts(events) == [events[4], events[2], events[5], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [
        event("before", 0, True), event("after", 5, True),
        event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 2, None), event("e", 4, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounded_rate_and_calendar_window():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 4, True), event("c", 6, None)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [event("a", 1, True)],
        "empty": [],
        "low": [event("b", 1, False)],
        "a": [event("c", 1, True)],
        "middle": [event("d", 1, True), event("e", 1, None)],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "middle", "low"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_keys_and_empty_value():
    groups = {"z": [], "b": [event("a", 1, None)], "a": [event("b", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 1.0, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [
    ([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3),
    ([1, 0, 2, 3, 0, 4], 2), ([1, -1, 2], 1), ([1, 2, 0], 2),
])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
